    #[test]
    fn test_empty() {
        let v: Vec<i8> = Vec::new();
        let c = copy(&v);
        assert_eq!(c, v);
    }

    #[test]
    fn test_non_empty() {
        let v = vec![-128, -1, 0, 1, 127];
        let c = copy(&v);
        assert_eq!(c, v);
    }

    #[test]
    fn test_multiple_copies_are_independent() {
        let v = vec![1, 2, 3];
        let mut c1 = copy(&v);
        let mut c2 = copy(&v);
        c1.push(4);
        c2.push(5);
        // original stays unchanged
        assert_eq!(v, vec![1, 2, 3]);
        // copies are independent
        assert_eq!(c1, vec![1, 2, 3, 4]);
        assert_eq!(c2, vec![1, 2, 3, 5]);
    }
